"use server";

import { createHash, randomBytes } from "crypto";
import { revalidatePath } from "next/cache";
import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";

/* Settings actions for the account area.
 *
 * `"use server"` makes EVERY export here network-callable, so each one calls
 * `requireUser()` itself and scopes every write to that user's own id. There is
 * no shared "already checked" state between them — a caller reaching one export
 * directly must be authorised by that export.
 *
 * Nothing here touches money, notification delivery, or anything that could
 * suppress a message: notification preferences live in `User.notificationPrefs`
 * behind lib/prefs.ts, which owns the policy about what may be suppressed.
 */

export type Res = { ok?: boolean; error?: string; value?: string };

const THEMES = new Set(["dark", "light", "system"]);
const DATE_FORMATS = new Set(["DMY", "MDY", "ISO"]);
const PER_PAGE = new Set([10, 25, 50, 100]);

/** Display preferences. Display only — none of this decides what is charged. */
export async function saveDisplayPrefs(_p: Res | undefined, form: FormData): Promise<Res> {
  const user = await requireUser();
  const theme = String(form.get("theme") ?? "dark");
  const dateFormat = String(form.get("dateFormat") ?? "DMY");
  const itemsPerPage = Number(form.get("itemsPerPage") ?? 25);
  const defaultPage = String(form.get("defaultPage") ?? "/dashboard");

  /* Validated against a closed set rather than stored as typed. A free string
     here would come back out into a `className` or a route. */
  if (!THEMES.has(theme)) return { error: "Unknown theme." };
  if (!DATE_FORMATS.has(dateFormat)) return { error: "Unknown date format." };
  if (!PER_PAGE.has(itemsPerPage)) return { error: "Unsupported page size." };
  if (!defaultPage.startsWith("/dashboard")) return { error: "That page is not a dashboard page." };

  await db.userPreference.upsert({
    where: { userId: user.id },
    create: { userId: user.id, theme, dateFormat, itemsPerPage, defaultPage },
    update: { theme, dateFormat, itemsPerPage, defaultPage },
  });
  revalidatePath("/dashboard/settings");
  return { ok: true };
}

/** Issue an API key. The plaintext is returned ONCE and never stored. */
export async function createApiKey(_p: Res | undefined, form: FormData): Promise<Res> {
  const user = await requireUser();
  const name = String(form.get("name") ?? "").trim().slice(0, 60);
  const scope = String(form.get("scope") ?? "full");
  if (name.length < 2) return { error: "Give the key a name you will recognise later." };
  if (!["full", "servers:read", "metrics:read"].includes(scope)) return { error: "Unknown scope." };

  const live = await db.apiKey.count({ where: { userId: user.id, revokedAt: null } });
  if (live >= 20) return { error: "You already have 20 active keys. Revoke one first." };

  /* 32 bytes of CSPRNG. The database gets only the SHA-256 and a display
     prefix, so a dump of this table is not a set of working credentials. */
  const secret = randomBytes(32).toString("base64url");
  const key = `nxk_live_${secret}`;
  await db.apiKey.create({
    data: {
      userId: user.id, name, scope,
      keyHash: createHash("sha256").update(key).digest("hex"),
      prefix: key.slice(0, 13),
    },
  });
  revalidatePath("/dashboard/settings");
  /* The one and only time this value exists outside the caller's hands. */
  return { ok: true, value: key };
}

export async function revokeApiKey(id: string): Promise<Res> {
  const user = await requireUser();
  /* Scoped to the caller's own id in the WHERE, not checked afterwards — a
     mismatched id updates nothing rather than revoking someone else's key. */
  const r = await db.apiKey.updateMany({
    where: { id, userId: user.id, revokedAt: null },
    data: { revokedAt: new Date() },
  });
  if (r.count === 0) return { error: "That key is already revoked, or is not yours." };
  revalidatePath("/dashboard/settings");
  return { ok: true };
}

export async function revokeSession(id: string): Promise<Res> {
  const user = await requireUser();
  const r = await db.userSession.updateMany({
    where: { id, userId: user.id, revokedAt: null },
    data: { revokedAt: new Date() },
  });
  if (r.count === 0) return { error: "That session has already ended." };
  revalidatePath("/dashboard/settings");
  return { ok: true };
}

/** End every OTHER session. The current one is left alone deliberately —
 *  signing yourself out of the page you are standing on is not what the
 *  control means. */
export async function revokeOtherSessions(currentTokenHash: string): Promise<Res> {
  const user = await requireUser();
  const r = await db.userSession.updateMany({
    where: { userId: user.id, revokedAt: null, NOT: { tokenHash: currentTokenHash } },
    data: { revokedAt: new Date() },
  });
  revalidatePath("/dashboard/settings");
  return { ok: true, value: String(r.count) };
}

"use client";

import { Icon } from "./Icon";
import { GlassFilters } from "./GlassFilters";

/* The page frame every account-area screen shares.
 *
 * WIDTH. These pages had no `max-width` at all, so they filled `<main>` — about
 * 1630px on a 1878px screen — while the dashboard is capped at 1520. That is
 * the whole reason they read as "very wide": nothing was holding them in. This
 * caps them at the SAME 1520 the dashboard uses, so the measure is identical
 * from page to page. (The original concept boards are tighter still, about
 * 1250 of content inside a 1536 board; `narrow` opts into that for pages whose
 * content is a single column of forms and rows rather than a grid, where a long
 * measure is genuinely harder to read.)
 *
 * HERO. Every concept screen opens the same way: a tracked magenta eyebrow, an
 * H1, one line of explanation, and the right-aligned tracked tagline block.
 * Reproducing that by hand on six pages is how six pages end up with six
 * slightly different heroes.
 */
export function PageShell({
  eyebrow, title, sub, tagline = ["SAME INFRASTRUCTURE.", "A BRIGHTER TOMORROW."],
  action, narrow = false, wisp = true, heroImage, children,
}: {
  eyebrow: string;
  title: string;
  sub?: string;
  /** The tracked block on the right. Two or three short lines, in caps. */
  tagline?: string[];
  /** Optional control in the hero's top-right (below the tagline on mobile). */
  action?: React.ReactNode;
  narrow?: boolean;
  /**
   * The static radial-gradient patch behind the header. Every other page with
   * its OWN animated aurora (Mail, Billing, Team, Support...) doesn't render
   * this header at all — it hand-rolls one and skips the wisp entirely, which
   * is why they never collided with it. Tools is the first page to keep using
   * this shared header while ALSO mounting a dedicated aurora underneath, and
   * the two stacked into a visible boxy patch on top of the animated one. Set
   * `false` when the page already supplies its own atmosphere.
   */
  wisp?: boolean;
  /**
   * A large decorative illustration anchored to the header's right side (a
   * real image, not a drawn glyph — e.g. the domains globe or the SSL shield).
   * Grows the header to give it real room instead of squeezing it into the
   * text row's leftover space.
   */
  heroImage?: string;
  children: React.ReactNode;
}) {
  return (
    <div className={"mx-auto flex w-full flex-col gap-4 " + (narrow ? "max-w-[1180px]" : "max-w-[1520px]")}>
      <header className={"relative overflow-hidden " + (heroImage ? "min-h-[280px] sm:min-h-[300px]" : "")}>
        {/* The aurora wisp the concept runs behind every hero. Decorative, so it
            is `pointer-events-none` and sits under the text. Skipped when a real
            hero image is present — the two washes fight for the same corner. */}
        {wisp && !heroImage && (
          <span aria-hidden
                className="pointer-events-none absolute -top-10 right-[16%] hidden h-[210px] w-[52%] opacity-70 md:block"
                style={{
                  background:
                    "radial-gradient(60% 120% at 50% 50%, rgba(64,150,255,0.20), transparent 70%)," +
                    "radial-gradient(38% 90% at 66% 42%, rgba(168,60,255,0.16), transparent 72%)",
                  filter: "blur(14px)",
                }} />
        )}
        {heroImage && (
          // eslint-disable-next-line @next/next/no-img-element -- a static hero illustration, not an optimizable content image.
          <img
            src={heroImage}
            alt=""
            aria-hidden
            className="pointer-events-none absolute -right-4 -top-6 hidden h-[280px] w-auto object-contain sm:block sm:h-[300px] lg:-right-2"
          />
        )}
        <div className="relative flex flex-wrap items-start justify-between gap-x-6 gap-y-3 pb-1">
          <div className="flex min-w-0 flex-col gap-1">
            <span className="text-[11px] font-extrabold uppercase tracking-[0.22em] text-[#f21cff]">{eyebrow}</span>
=== PREFS ===
/**
 * Notification preferences: the stored shape, the pure helpers — and the POLICY
 * that decides which messages those preferences are allowed to suppress.
 *
 * Plain module (safe to import from server components; client components must
 * import TYPES ONLY — the `mayDeliverTo` helper below reaches for `./db`). The
 * `"use server"` action file may only export async functions, so all of this
 * lives here.
 *
 * WHY THIS FILE GREW A POLICY (2026-07-26)
 * ---------------------------------------------------------------------------
 * `User.notificationPrefs` was written by the settings form and read by NOTHING
 * (QA-PRELAUNCH P1-32). A customer who unticked "Account email" still received
 * every receipt; the "Security alerts" toggle governed a channel that was never
 * built. That is the same defect this codebase keeps shipping: a control that
 * reports success and is read by nothing — the auto-suspend kill switch an
 * operator turned off before watching customer VMs get suspended anyway
 * (P1-5), and the domain-markup panel that displayed 0% while charging 25%
 * (P1-9).
 *
 * The dangerous half of fixing it is OVER-fixing it. If a preference could
 * suppress a declined payment, an imminent suspension, a security/2FA change or
 * a data-loss warning, then an unticked checkbox would silently swallow the one
 * message the customer had to see — and they would lose a server, or an
 * account, with no warning at all. That is strictly worse than the original bug.
 *
 * So suppressibility is decided by a message's TIER, declared once in the
 * catalogue below, and never by the call site. A send site cannot make itself
 * suppressible by passing the wrong flag, and an unrecognised kind resolves to
 * CRITICAL — if we guess wrong, we guess towards "delivered".
 */

export type NotificationPrefs = {
  /**
   * Non-urgent transactional EMAIL: payment receipts, activity notices.
   * Never covers the dunning sequence, suspensions or security changes.
   */
  email: boolean;
  /**
   * Product news / marketing. Unticking this also removes the address from the
   * campaign list (see `updateNotificationPrefs`) — the stored flag alone would
   * suppress nothing, because campaigns are addressed by email, not by user.
   */
  product: boolean;
  /**
   * Legacy key, pinned `true`.
   *
   * It used to render as a "Security alerts" toggle, which was dishonest twice
   * over: the channel it claimed to govern was never built (sign-in / token /
   * 2FA paths write audit rows only), and security, password and 2FA messages
   * must not be suppressible in the first place. Kept in the shape so
   * previously-stored values and the GDPR export keep round-tripping, and typed
   * as the literal `true` so no code path can ever write it back as
   * consent-withdrawn.
   */
  security: true;
};

export const DEFAULT_PREFS: NotificationPrefs = { email: true, product: true, security: true };

/**
 * Normalise whatever is stored in the Json column into a typed prefs object.
 * A missing or malformed key falls back to the default (opted IN) — the column
 * is nullable and predates this policy, so "absent" must never read as "the
 * customer opted out of everything".
 */
export function normalizePrefs(raw: unknown): NotificationPrefs {
  const p = (raw ?? {}) as Record<string, unknown>;
  return {
    email: typeof p.email === "boolean" ? p.email : DEFAULT_PREFS.email,
    product: typeof p.product === "boolean" ? p.product : DEFAULT_PREFS.product,
    security: true,
  };
}

/* -------------------------------------------------------------------------- */
/*                          Delivery policy                                   */
/* -------------------------------------------------------------------------- */

/** How a message reaches the customer. */

