/* ── stat tile ──────────────────────────────────────────────────────────
   The concept's tile: a tinted, bordered icon square (not a solid brand
   plate), the figure beside it, label under, and an optional coloured
   delta line. Local to this page — it is this page's own look, not a
   change to the shared StatCard every other page uses. */
const TILE = {
  blue:  { ink: "text-[#7fb0ff]" },
  green: { ink: "text-emerald-400" },
  amber: { ink: "text-orange-400" },
} as const;

function Stat({
  icon, tone, value, label, foot,
}: {
  icon: string; tone: keyof typeof TILE; value: string; label: string; foot?: React.ReactNode;
}) {
  const t = TILE[tone];
  return (
    <div className="flex min-w-0 items-start gap-3.5 rounded-[15px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.55),rgba(2,7,20,.6))] px-4 py-3.5">
      <Icon name={icon} size={24} tone="inherit" className={"mt-0.5 flex-none " + t.ink} />
      <span className="flex min-w-0 flex-col">
        <span className="num text-[23px] font-bold leading-none text-white">{value}</span>
        <span className="mt-1 text-[13px] text-tx-dim">{label}</span>
        {foot}
      </span>
    </div>
  );
}

