function MigrationProgress({ id, onDone }: { id: string; onDone: () => void }) {
  const [row, setRow] = useState<MigrationRow | null>(null);
  const [error, setError] = useState<string | null>(null);
  // Fetched ONCE the migration reaches a terminal state, and shared by both the
  // cutover card and the rollback card so a finished migration makes a single
  // round trip for its domain list.
  const [dns, setDns] = useState<MigrationDnsInfo | null>(null);

  useEffect(() => {
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout>;

    async function poll() {
      try {
        const m = await getMigration(id);
        if (cancelled) return;
        setRow(m);
        // COMPLETED_WITH_ISSUES is terminal too — the move finished but at least
        // one source domain is dark or a migrated unit is crash-looping. If it
        // isn't listed here the wizard polls forever and never renders a result.
        if (m && (m.status === "DONE" || m.status === "COMPLETED_WITH_ISSUES" || m.status === "FAILED")) return;
      } catch {
        if (!cancelled) setError("Lost connection while checking progress.");
      }
      if (!cancelled) timer = setTimeout(poll, 3000);
    }
    poll();
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [id]);

  const progress = row?.progress ?? 0;
  // Finished-but-not-fully-live. Counts as `done` so the result view renders at
  // all, but is surfaced separately — a migration that left domains dark must not
  // look identical to a clean one.
  const withIssues = row?.status === "COMPLETED_WITH_ISSUES";
  const done = row?.status === "DONE" || withIssues;
  const failed = row?.status === "FAILED";
  const terminal = done || failed;

  useEffect(() => {
    if (!terminal) return;
    let cancelled = false;
    getMigrationDnsInfo(id)
      .then((res) => {
        if (!cancelled) setDns(res);
      })
      .catch(() => {
        if (!cancelled) setDns({ error: "Couldn't load your domains right now." });
      });
    return () => {
      cancelled = true;
    };
  }, [id, terminal]);

  return (
    <div className="space-y-6">
      <CloudflareResultBanner />
      <div className="card">
        <div className="mb-4 flex items-center justify-between">
          <h2 className="font-semibold">Migration in progress</h2>
          {row && <StatusDot status={row.status} />}
        </div>

        {error && <div className="mb-4 rounded-xl border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-sm text-amber-300">{error}</div>}

        <div className="mb-2 flex items-center justify-between text-sm">
          <span className="text-slate-300">{row?.step ?? "Queued…"}</span>
          <span className="font-semibold">{progress}%</span>

