function toRow(
  m: {
    id: string;
    serverId: string;
    sourceHost: string;
    sourcePort: number;
    sourceUser: string;
    items: unknown;
    status: string;
    progress: number;
    step: string | null;
    log: string | null;
    lastError: string | null;
    createdAt: Date;
    finishedAt: Date | null;
  },
  server: { hostname: string; label: string | null } | null
): MigrationRow {
  const items = (m.items ?? {}) as {
    paths?: string[];
    databases?: { engine?: string; name?: string; user?: string }[];
    dbEngines?: string[];
  };
  // Databases are now auto-included per detected engine (no per-DB list). For the
  // client view, surface one row per engine; fall back to any legacy per-DB list.
  const dbView: MigrationDatabaseView[] =
    Array.isArray(items.databases) && items.databases.length
      ? items.databases.map((d) => ({
          engine: String(d.engine ?? ""),
          name: String(d.name ?? ""),
          user: String(d.user ?? ""),
        }))
      : Array.isArray(items.dbEngines)
        ? items.dbEngines.map((e) => ({ engine: String(e), name: "All databases", user: "root" }))
        : [];
  return {
    id: m.id,
    serverId: m.serverId,
    // Migration has no Prisma relation to Server (serverId is a plain FK), so the
    // caller resolves the server row and passes it in.
    serverName: server ? server.label || server.hostname : null,
    sourceHost: m.sourceHost,
    sourcePort: m.sourcePort,
    sourceUser: m.sourceUser,
    paths: Array.isArray(items.paths) ? items.paths : [],
    // Never expose any DB secret — dbView carries only non-sensitive fields.
    databases: dbView,
    status: m.status,
    progress: m.progress,
    step: m.step,
    log: m.log,
    lastError: m.lastError,
    createdAt: m.createdAt.toISOString(),
    finishedAt: m.finishedAt ? m.finishedAt.toISOString() : null,
  };
}

